package main

import (
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type cliArgs struct {
	file         string
	subcmd       string
	printHelp    bool
	printVersion bool

	// per-subcommand options
	description    *string
	project        *string
	timeStr        *string
	editor         *string
	dateStr        *string
	fromDateStr    *string
	toDateStr      *string
	roundStr       *string
	number         *string
	searchTerm     string
	currentWeek    bool
	lastWeek       bool
	today          bool
	yesterday      bool
	noGrouping     bool
	currentFlag    bool
	noQuotes       bool
	continueNumber int
	// For help of subsubcommand
	helpSubcmd string
}

// knownSubcommands
var subcommands = []string{
	"cancel", "change", "check", "continue", "current", "edit", "help",
	"last", "list", "projects", "report", "sanity", "search", "start",
	"status", "stop",
}

func isSubcommand(s string) bool {
	for _, x := range subcommands {
		if x == s {
			return true
		}
	}
	return false
}

// parseCLI parses all args.
func parseCLI(args []string) (*cliArgs, error) {
	cli := &cliArgs{}

	i := 0
	// Parse top-level options/flags
	for i < len(args) {
		a := args[i]
		if a == "-h" || a == "--help" {
			cli.printHelp = true
			return cli, nil
		}
		if a == "-V" || a == "--version" {
			cli.printVersion = true
			return cli, nil
		}
		if a == "-f" {
			// value is next
			if i+1 >= len(args) {
				// Like clap: if -f has no value, just show help (no subcommand found)
				return cli, nil
			}
			cli.file = args[i+1]
			i += 2
			continue
		}
		if strings.HasPrefix(a, "-f") && len(a) > 2 {
			cli.file = a[2:]
			i++
			continue
		}
		if strings.HasPrefix(a, "-") {
			// Unknown top-level arg
			return nil, fmt.Errorf("error: Found argument '%s' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable [OPTIONS] <SUBCOMMAND>\n\nFor more information try --help", a)
		}
		// Must be subcommand
		cli.subcmd = a
		i++
		if !isSubcommand(cli.subcmd) {
			return nil, fmt.Errorf("error: Found argument '%s' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable [OPTIONS] <SUBCOMMAND>\n\nFor more information try --help", cli.subcmd)
		}
		break
	}
	if cli.subcmd == "" {
		if cli.file == "" {
			// No file, no subcommand => print help (like clap default)
		}
		return cli, nil
	}
	// From env var
	if cli.file == "" {
		cli.file = os.Getenv("BARTIB_FILE")
	}

	// Parse subcommand args
	remaining := args[i:]
	if err := parseSubArgs(cli, remaining); err != nil {
		return nil, err
	}
	return cli, nil
}

func parseSubArgs(cli *cliArgs, args []string) error {
	sc := cli.subcmd
	// Each subcommand has its own definition
	spec := subcmdSpec(sc)
	if spec == nil {
		return fmt.Errorf("unknown subcommand: %s", sc)
	}
	// Use spec to parse
	return spec.parse(cli, args)
}

type argSpec struct {
	subcmd string
	// flags: map from flag name (including dashes) to boolean pointer
	flags map[string]func(*cliArgs)
	// options: map from option name (including dashes) to string pointer
	options map[string]func(*cliArgs, string)
	// positional: ordered list of positional targets
	positional []func(*cliArgs, string) error
	// required options (long names) — for validation
	required []string
	// canonical long names for error messages
	longNames map[string]string // short name -> long name
	// required by option
	optionMeta map[string]string // long name -> META (like DESCRIPTION)
	// number of positional args expected (for usage formatting in errors)
	maxPositional int
}

func subcmdSpec(name string) *argSpec {
	switch name {
	case "cancel":
		return &argSpec{subcmd: name}
	case "change":
		s := &argSpec{subcmd: name}
		s.options = map[string]func(*cliArgs, string){
			"-d":            func(c *cliArgs, v string) { c.description = &v },
			"--description": func(c *cliArgs, v string) { c.description = &v },
			"-p":            func(c *cliArgs, v string) { c.project = &v },
			"--project":     func(c *cliArgs, v string) { c.project = &v },
			"-t":            func(c *cliArgs, v string) { c.timeStr = &v },
			"--time":        func(c *cliArgs, v string) { c.timeStr = &v },
		}
		s.optionMeta = map[string]string{"--description": "DESCRIPTION", "--project": "PROJECT", "--time": "TIME"}
		return s
	case "check":
		return &argSpec{subcmd: name}
	case "continue":
		s := &argSpec{subcmd: name}
		s.options = map[string]func(*cliArgs, string){
			"-d":            func(c *cliArgs, v string) { c.description = &v },
			"--description": func(c *cliArgs, v string) { c.description = &v },
			"-p":            func(c *cliArgs, v string) { c.project = &v },
			"--project":     func(c *cliArgs, v string) { c.project = &v },
			"-t":            func(c *cliArgs, v string) { c.timeStr = &v },
			"--time":        func(c *cliArgs, v string) { c.timeStr = &v },
		}
		s.optionMeta = map[string]string{"--description": "DESCRIPTION", "--project": "PROJECT", "--time": "TIME"}
		s.positional = []func(*cliArgs, string) error{
			func(c *cliArgs, v string) error {
				n, err := strconv.Atoi(v)
				if err != nil {
					return fmt.Errorf("could not parse %q as number", v)
				}
				c.continueNumber = n
				return nil
			},
		}
		s.maxPositional = 1
		return s
	case "current":
		return &argSpec{subcmd: name}
	case "edit":
		s := &argSpec{subcmd: name}
		s.options = map[string]func(*cliArgs, string){
			"-e": func(c *cliArgs, v string) { c.editor = &v },
		}
		s.optionMeta = map[string]string{"-e": "editor"}
		return s
	case "help":
		s := &argSpec{subcmd: name}
		s.positional = []func(*cliArgs, string) error{
			func(c *cliArgs, v string) error {
				c.helpSubcmd = v
				return nil
			},
		}
		s.maxPositional = 1
		return s
	case "last":
		s := &argSpec{subcmd: name}
		s.options = map[string]func(*cliArgs, string){
			"-n":       func(c *cliArgs, v string) { c.number = &v },
			"--number": func(c *cliArgs, v string) { c.number = &v },
		}
		s.optionMeta = map[string]string{"--number": "NUMBER"}
		return s
	case "list":
		s := &argSpec{subcmd: name}
		s.flags = map[string]func(*cliArgs){
			"--current_week": func(c *cliArgs) { c.currentWeek = true },
			"--last_week":    func(c *cliArgs) { c.lastWeek = true },
			"--no_grouping":  func(c *cliArgs) { c.noGrouping = true },
			"--today":        func(c *cliArgs) { c.today = true },
			"--yesterday":    func(c *cliArgs) { c.yesterday = true },
		}
		s.options = map[string]func(*cliArgs, string){
			"-d":        func(c *cliArgs, v string) { c.dateStr = &v },
			"--date":    func(c *cliArgs, v string) { c.dateStr = &v },
			"--from":    func(c *cliArgs, v string) { c.fromDateStr = &v },
			"--to":      func(c *cliArgs, v string) { c.toDateStr = &v },
			"-n":        func(c *cliArgs, v string) { c.number = &v },
			"--number":  func(c *cliArgs, v string) { c.number = &v },
			"-p":        func(c *cliArgs, v string) { c.project = &v },
			"--project": func(c *cliArgs, v string) { c.project = &v },
			"--round":   func(c *cliArgs, v string) { c.roundStr = &v },
		}
		s.optionMeta = map[string]string{
			"--date": "DATE", "--from": "FROM_DATE", "--to": "TO_DATE",
			"--number": "NUMBER", "--project": "PROJECT", "--round": "round",
		}
		return s
	case "projects":
		s := &argSpec{subcmd: name}
		s.flags = map[string]func(*cliArgs){
			"-c":          func(c *cliArgs) { c.currentFlag = true },
			"--current":   func(c *cliArgs) { c.currentFlag = true },
			"-n":          func(c *cliArgs) { c.noQuotes = true },
			"--no-quotes": func(c *cliArgs) { c.noQuotes = true },
		}
		return s
	case "report":
		s := &argSpec{subcmd: name}
		s.flags = map[string]func(*cliArgs){
			"--current_week": func(c *cliArgs) { c.currentWeek = true },
			"--last_week":    func(c *cliArgs) { c.lastWeek = true },
			"--today":        func(c *cliArgs) { c.today = true },
			"--yesterday":    func(c *cliArgs) { c.yesterday = true },
		}
		s.options = map[string]func(*cliArgs, string){
			"-d":        func(c *cliArgs, v string) { c.dateStr = &v },
			"--date":    func(c *cliArgs, v string) { c.dateStr = &v },
			"--from":    func(c *cliArgs, v string) { c.fromDateStr = &v },
			"--to":      func(c *cliArgs, v string) { c.toDateStr = &v },
			"-p":        func(c *cliArgs, v string) { c.project = &v },
			"--project": func(c *cliArgs, v string) { c.project = &v },
			"--round":   func(c *cliArgs, v string) { c.roundStr = &v },
		}
		s.optionMeta = map[string]string{
			"--date": "DATE", "--from": "FROM_DATE", "--to": "TO_DATE",
			"--project": "PROJECT", "--round": "round",
		}
		return s
	case "sanity":
		return &argSpec{subcmd: name}
	case "search":
		s := &argSpec{subcmd: name}
		s.positional = []func(*cliArgs, string) error{
			func(c *cliArgs, v string) error { c.searchTerm = v; return nil },
		}
		s.maxPositional = 1
		return s
	case "start":
		s := &argSpec{subcmd: name}
		s.options = map[string]func(*cliArgs, string){
			"-d":            func(c *cliArgs, v string) { c.description = &v },
			"--description": func(c *cliArgs, v string) { c.description = &v },
			"-p":            func(c *cliArgs, v string) { c.project = &v },
			"--project":     func(c *cliArgs, v string) { c.project = &v },
			"-t":            func(c *cliArgs, v string) { c.timeStr = &v },
			"--time":        func(c *cliArgs, v string) { c.timeStr = &v },
		}
		s.optionMeta = map[string]string{"--description": "DESCRIPTION", "--project": "PROJECT", "--time": "TIME"}
		s.required = []string{"--description", "--project"}
		return s
	case "status":
		s := &argSpec{subcmd: name}
		s.options = map[string]func(*cliArgs, string){
			"-p":        func(c *cliArgs, v string) { c.project = &v },
			"--project": func(c *cliArgs, v string) { c.project = &v },
		}
		s.optionMeta = map[string]string{"--project": "PROJECT"}
		return s
	case "stop":
		s := &argSpec{subcmd: name}
		s.options = map[string]func(*cliArgs, string){
			"-t":     func(c *cliArgs, v string) { c.timeStr = &v },
			"--time": func(c *cliArgs, v string) { c.timeStr = &v },
		}
		s.optionMeta = map[string]string{"--time": "TIME"}
		return s
	}
	return nil
}

func (s *argSpec) parse(cli *cliArgs, args []string) error {
	posIdx := 0
	seen := map[string]bool{}
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "-h" || a == "--help" {
			fmt.Print(subcmdHelp(s.subcmd))
			os.Exit(0)
		}
		// Check for long options with "=value"
		if strings.HasPrefix(a, "--") {
			key, val, hasEq := strings.Cut(a, "=")
			if setter, ok := s.options[key]; ok {
				if hasEq {
					setter(cli, val)
				} else {
					if i+1 >= len(args) {
						return errRequiresValue(key, s)
					}
					setter(cli, args[i+1])
					i++
				}
				seen[key] = true
				continue
			}
			if flag, ok := s.flags[key]; ok {
				if hasEq {
					return fmt.Errorf("error: Found argument '%s' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n%s\n\nFor more information try --help", a, "    "+subcmdUsage(s.subcmd))
				}
				flag(cli)
				seen[key] = true
				continue
			}
			return errUnknownArg(a, s)
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 && !isNegativeNumber(a) {
			// short option or flag
			key := a[:2]
			rest := a[2:]
			if setter, ok := s.options[key]; ok {
				if rest != "" {
					setter(cli, rest)
				} else {
					if i+1 >= len(args) {
						return errRequiresValue(key, s)
					}
					setter(cli, args[i+1])
					i++
				}
				seen[key] = true
				continue
			}
			if flag, ok := s.flags[key]; ok {
				if rest != "" {
					return errUnknownArg(a, s)
				}
				flag(cli)
				seen[key] = true
				continue
			}
			return errUnknownArg(a, s)
		}
		// positional
		if posIdx >= s.maxPositional {
			return errUnknownArg(a, s)
		}
		if err := s.positional[posIdx](cli, a); err != nil {
			return err
		}
		posIdx++
	}
	// Check required options
	var missing []string
	for _, r := range s.required {
		// Check whether any alias for this long name was seen
		for k := range s.options {
			if k == r && seen[k] {
				missing = nil
				goto nextReq
			}
		}
		// Also check matching short option alias
		if seenOptionBySetter(s, cli, r) {
			goto nextReq
		}
		missing = append(missing, r)
	nextReq:
	}
	if len(missing) > 0 {
		return errMissingRequired(s, missing)
	}
	return nil
}

func seenOptionBySetter(s *argSpec, cli *cliArgs, longName string) bool {
	switch longName {
	case "--description":
		return cli.description != nil
	case "--project":
		return cli.project != nil
	case "--time":
		return cli.timeStr != nil
	}
	return false
}

func isNegativeNumber(s string) bool {
	if len(s) < 2 {
		return false
	}
	for i := 1; i < len(s); i++ {
		c := s[i]
		if c == '.' {
			continue
		}
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func errUnknownArg(a string, s *argSpec) error {
	return fmt.Errorf("error: Found argument '%s' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n%s\n\nFor more information try --help", a, "    "+subcmdUsage(s.subcmd))
}

func errRequiresValue(optName string, s *argSpec) error {
	meta := s.optionMeta[optName]
	fullName := longForShort(s, optName)
	// Build usage line combining required + current option
	usage := errUsageWithAll(s, fullName)
	return fmt.Errorf("error: The argument '%s <%s>' requires a value but none was supplied\n\nUSAGE:\n    %s\n\nFor more information try --help", fullName, meta, usage)
}

func longForShort(s *argSpec, opt string) string {
	if strings.HasPrefix(opt, "--") {
		return opt
	}
	// Find long name that has same setter signature (heuristic: hardcoded)
	aliases := map[string]string{
		"-d": "--description", "-p": "--project", "-t": "--time",
		"-n": "--number", "-e": "-e",
	}
	if v, ok := aliases[opt]; ok {
		return v
	}
	return opt
}

func errUsageWithAll(s *argSpec, currentLong string) string {
	// Mimic clap behavior: usage shows required + supplied option
	// Usage example:
	//   executable start --description <DESCRIPTION> --project <PROJECT> --time <TIME>
	var parts []string
	parts = append(parts, "executable", s.subcmd)
	// Required first in order
	added := map[string]bool{}
	for _, r := range s.required {
		if meta, ok := s.optionMeta[r]; ok {
			parts = append(parts, fmt.Sprintf("%s <%s>", r, meta))
			added[r] = true
		}
	}
	// Then the current option if not already included
	if currentLong != "" && !added[currentLong] {
		if meta, ok := s.optionMeta[currentLong]; ok {
			parts = append(parts, fmt.Sprintf("%s <%s>", currentLong, meta))
		}
	}
	return strings.Join(parts, " ")
}

func errMissingRequired(s *argSpec, missing []string) error {
	var lines []string
	lines = append(lines, "error: The following required arguments were not provided:")
	for _, m := range missing {
		if meta, ok := s.optionMeta[m]; ok {
			lines = append(lines, fmt.Sprintf("    %s <%s>", m, meta))
		}
	}
	lines = append(lines, "")
	lines = append(lines, "USAGE:")
	lines = append(lines, "    "+subcmdUsage(s.subcmd))
	lines = append(lines, "")
	lines = append(lines, "For more information try --help")
	return errors.New(strings.Join(lines, "\n"))
}
GOEOF

