func (s *argSpec) parse(cli *cliArgs, args []string) error {
	posIdx := 0
	seen := map[string]bool{}
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "-h" || a == "--help" {
			fmt.Print(subcmdHelp(s.subcmd))
			os.Exit(0)
		}
		// Check for long options with "=value"
		if strings.HasPrefix(a, "--") {
			key, val, hasEq := strings.Cut(a, "=")
			if setter, ok := s.options[key]; ok {
				if hasEq {
					setter(cli, val)
				} else {
					if i+1 >= len(args) {
						return errRequiresValue(key, s)
					}
					setter(cli, args[i+1])
					i++
				}
				seen[key] = true
				continue
			}
			if flag, ok := s.flags[key]; ok {
				if hasEq {
					return fmt.Errorf("error: Found argument '%s' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n%s\n\nFor more information try --help", a, "    "+subcmdUsage(s.subcmd))
				}
				flag(cli)
				seen[key] = true
				continue
			}
			return errUnknownArg(a, s)
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 && !isNegativeNumber(a) {
			// short option or flag
			key := a[:2]
			rest := a[2:]
			if setter, ok := s.options[key]; ok {
				if rest != "" {
					setter(cli, rest)
				} else {
					if i+1 >= len(args) {
						return errRequiresValue(key, s)
					}
					setter(cli, args[i+1])
					i++
				}
				seen[key] = true
				continue
			}
			if flag, ok := s.flags[key]; ok {
				if rest != "" {
					return errUnknownArg(a, s)
				}
				flag(cli)
				seen[key] = true
				continue
			}
			return errUnknownArg(a, s)
		}
		// positional
		if posIdx >= s.maxPositional {
			return errUnknownArg(a, s)
		}
		if err := s.positional[posIdx](cli, a); err != nil {
			return err
		}
		posIdx++
	}
	// Check required options
	var missing []string
	for _, r := range s.required {
		// Check whether any alias for this long name was seen
		for k := range s.options {
			if k == r && seen[k] {
				missing = nil
				goto nextReq
			}
		}
		// Also check matching short option alias
		if seenOptionBySetter(s, cli, r) {
			goto nextReq
		}
		missing = append(missing, r)
	nextReq:
	}
	if len(missing) > 0 {
		return errMissingRequired(s, missing)
	}
	return nil
}

func seenOptionBySetter(s *argSpec, cli *cliArgs, longName string) bool {
	switch longName {
	case "--description":
		return cli.description != nil
	case "--project":
		return cli.project != nil
	case "--time":
		return cli.timeStr != nil
	}
	return false
}

func isNegativeNumber(s string) bool {
	if len(s) < 2 {
		return false
	}
	for i := 1; i < len(s); i++ {
		c := s[i]
		if c == '.' {
			continue
		}
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func errUnknownArg(a string, s *argSpec) error {
	return fmt.Errorf("error: Found argument '%s' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n%s\n\nFor more information try --help", a, "    "+subcmdUsage(s.subcmd))
}

func errRequiresValue(optName string, s *argSpec) error {
	meta := s.optionMeta[optName]
	fullName := longForShort(s, optName)
	// Build usage line combining required + current option
	usage := errUsageWithAll(s, fullName)
	return fmt.Errorf("error: The argument '%s <%s>' requires a value but none was supplied\n\nUSAGE:\n    %s\n\nFor more information try --help", fullName, meta, usage)
}

func longForShort(s *argSpec, opt string) string {
	if strings.HasPrefix(opt, "--") {
		return opt
	}
	// Find long name that has same setter signature (heuristic: hardcoded)
	aliases := map[string]string{
		"-d": "--description", "-p": "--project", "-t": "--time",
		"-n": "--number", "-e": "-e",
	}
	if v, ok := aliases[opt]; ok {
		return v
	}
	return opt
}

func errUsageWithAll(s *argSpec, currentLong string) string {
	// Mimic clap behavior: usage shows required + supplied option
	// Usage example:
	//   executable start --description <DESCRIPTION> --project <PROJECT> --time <TIME>
	var parts []string
	parts = append(parts, "executable", s.subcmd)
	// Required first in order
	added := map[string]bool{}
	for _, r := range s.required {
		if meta, ok := s.optionMeta[r]; ok {
			parts = append(parts, fmt.Sprintf("%s <%s>", r, meta))
			added[r] = true
		}
	}
	// Then the current option if not already included
	if currentLong != "" && !added[currentLong] {
		if meta, ok := s.optionMeta[currentLong]; ok {
			parts = append(parts, fmt.Sprintf("%s <%s>", currentLong, meta))
		}
	}
	return strings.Join(parts, " ")
}

func errMissingRequired(s *argSpec, missing []string) error {
	var lines []string
	lines = append(lines, "error: The following required arguments were not provided:")
	for _, m := range missing {
		if meta, ok := s.optionMeta[m]; ok {
			lines = append(lines, fmt.Sprintf("    %s <%s>", m, meta))
		}
	}
	lines = append(lines, "")
	lines = append(lines, "USAGE:")
	lines = append(lines, "    "+subcmdUsage(s.subcmd))
	lines = append(lines, "")
	lines = append(lines, "For more information try --help")
	return errors.New(strings.Join(lines, "\n"))
}
