package main

import (
	"fmt"
	"os"
)

type Log struct {
	Path       string
	Entries    []ParsedActivity
	Activities []*Activity // only successfully parsed activities
}

func loadLog(path string) (*Log, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("Could not read from file: %s\n\nCaused by:\n    %s", path, errCause(err))
	}
	entries := parseLog(string(data))
	var acts []*Activity
	for _, e := range entries {
		if e.Activity != nil {
			acts = append(acts, e.Activity)
		}
	}
	return &Log{Path: path, Entries: entries, Activities: acts}, nil
}

func errCause(err error) string {
	if pe, ok := err.(*os.PathError); ok {
		return pe.Err.Error() + " (os error 2)"
	}
	return err.Error()
}

// appendLine appends a new activity line to the log file.
func appendLine(path, line string) error {
	f, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		return fmt.Errorf("Could not open file for writing: %s\n\nCaused by:\n    %s", path, err.Error())
	}
	defer f.Close()
	_, err = f.WriteString(line + "\n")
	return err
}

// rewriteFile rewrites the entire log file, preserving unparsed lines at their positions.
func rewriteFile(path string, entries []ParsedActivity) error {
	// Re-read original file to preserve blank lines exactly (they are skipped in parsing)
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	origLines := splitLines(string(data))
	// Build a map of lineNo -> new line content (from entries that have been modified).
	mods := map[int]string{}
	for _, e := range entries {
		if e.Activity != nil {
			mods[e.Line] = formatActivityLine(e.Activity)
		}
	}
	var out []string
	for i, line := range origLines {
		lineNo := i + 1
		if v, ok := mods[lineNo]; ok {
			out = append(out, v)
		} else {
			out = append(out, line)
		}
	}
	// Write
	f, err := os.Create(path)
	if err != nil {
		return err
	}
	defer f.Close()
	for i, line := range out {
		if i == len(out)-1 && line == "" {
			// preserve trailing newline if present
			// But writing a trailing empty line gives trailing newline naturally
			_, _ = f.WriteString("\n")
			break
		}
		if _, err := f.WriteString(line + "\n"); err != nil {
			return err
		}
	}
	// Handle case where original file ended without trailing newline
	return nil
}

func splitLines(content string) []string {
	// Strip single trailing newline so each line is one entry
	if len(content) > 0 && content[len(content)-1] == '\n' {
		content = content[:len(content)-1]
	}
	return stringSplit(content, '\n')
}

func stringSplit(s string, sep byte) []string {
	var out []string
	start := 0
	for i := 0; i < len(s); i++ {
		if s[i] == sep {
			out = append(out, s[start:i])
			start = i + 1
		}
	}
	out = append(out, s[start:])
	return out
}
