	"time"
)

// ANSI constants
const (
	ansiReset     = "\x1b[0m"
	ansiBold      = "\x1b[1m"
	ansiDim       = "\x1b[2m"
	ansiItalic    = "\x1b[3m"
	ansiUnderline = "\x1b[4m"
	ansiBoldGreen = "\x1b[1;32m"
	ansiYellow    = "\x1b[33m"
	ansiDimItalic = "\x1b[2;3m"
)

// nbsp is a non-breaking space (U+00A0, UTF-8 0xC2 0xA0).
const nbsp = "\u00a0"

// formatDuration returns a human-readable duration string per bartib rules.
func formatDuration(d time.Duration) string {
	if d < time.Minute {
		return "<1m"
	}
	total := int(d / time.Minute)
	h := total / 60
	m := total % 60
	if h == 0 {
		return fmt.Sprintf("%02dm", m)
	}
	return fmt.Sprintf("%dh %02dm", h, m)
}

// padNBSP pads a string with NBSP up to visualLen characters.
func padNBSP(s string, width int) string {
	visual := runeLen(s)
	if visual >= width {
		return s
	}
	return s + strings.Repeat(nbsp, width-visual)
}

// runeLen returns the number of runes in s.
func runeLen(s string) int {
	return len([]rune(s))
}

// stripAnsi removes ANSI escape sequences from s for width measurement.
func stripAnsi(s string) string {
	var b strings.Builder
	i := 0
	for i < len(s) {
		if s[i] == 0x1b && i+1 < len(s) && s[i+1] == '[' {
			j := i + 2
			for j < len(s) && s[j] != 'm' {
				j++
			}
			if j < len(s) {
				i = j + 1
				continue
			}
		}
		b.WriteByte(s[i])
		i++
	}
	return b.String()
}

// colWidth returns max of header width and content widths.
func colWidth(header string, contents ...string) int {
	w := runeLen(header)
	for _, c := range contents {
		cw := runeLen(stripAnsi(c))
		if cw > w {
			w = cw
		}
	}
	return w
}

// boldLine returns a bolded string.
func bold(s string) string     { return ansiBold + s + ansiReset }
func underline(s string) string { return ansiUnderline + s + ansiReset }
func yellow(s string) string   { return ansiYellow + s + ansiReset }

// dayHeader returns the bold group header (date + duration).
func dayHeader(date time.Time, totalDur time.Duration) string {
	return bold(date.Format("2006-01-02") + "\t" + formatDuration(totalDur))
}
