func cmdCancel(cli *cliArgs) error {
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	// Remove running entries
	var canceled []*Activity
	var keep []ParsedActivity
	for _, e := range log.Entries {
		if e.Activity != nil && e.Activity.IsRunning() {
			canceled = append(canceled, e.Activity)
			continue
		}
		keep = append(keep, e)
	}
	for _, c := range canceled {
		fmt.Printf("Canceled activity: %q (%s) started at %s\n",
			c.Description, c.Project, c.Start.Format("2006-01-02 15:04"))
	}
	if len(canceled) > 0 {
		return removeLinesAndRewrite(cli.file, log.Entries, canceled)
	}
	return nil
}

// removeLinesAndRewrite removes the specified activities' lines from the original file.
func removeLinesAndRewrite(path string, entries []ParsedActivity, toRemove []*Activity) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	origLines := splitLines(string(data))
	skip := map[int]bool{}
	for _, r := range toRemove {
		skip[r.Line] = true
	}
	// Also apply modifications from entries (those that remain).
	mods := map[int]string{}
	for _, e := range entries {
		if e.Activity != nil && !skip[e.Line] {
			mods[e.Line] = formatActivityLine(e.Activity)
		}
	}
	f, err := os.Create(path)
	if err != nil {
		return err
	}
	defer f.Close()
	for i, line := range origLines {
		lineNo := i + 1
		if skip[lineNo] {
			continue
		}
		if v, ok := mods[lineNo]; ok {
			line = v
		}
		if _, err := f.WriteString(line + "\n"); err != nil {
			return err
		}
	}
	return nil
}

func cmdCurrent(cli *cliArgs) error {
