func cmdLast(cli *cliArgs) error {
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	limit := 10
	if cli.number != nil {
		if n, err := strconv.Atoi(*cli.number); err == nil && n > 0 {
			limit = n
		}
	}
	prior := collectLastActivities(log, limit)
	if len(prior) == 0 {
		return fmt.Errorf("Error: No activity has been started before.")
	}
	// Print in ascending order (highest index first, then [0] at bottom)
	// prior[0] is most recent. We display in reverse.
	rows := make([][]string, 0, len(prior))
	for i := len(prior) - 1; i >= 0; i-- {
		rows = append(rows, []string{
			fmt.Sprintf("[%d]", i),
			prior[i].Description,
			prior[i].Project,
		})
	}
	writeTable([]string{" # ", "Description", "Project"}, rows, nil)
	return nil
}

func cmdSearch(cli *cliArgs) error {
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	term := strings.ToLower(cli.searchTerm)
	prior := collectLastActivities(log, 0)
	var matches []*Activity
	for _, a := range prior {
		if strings.Contains(strings.ToLower(a.Description), term) || strings.Contains(strings.ToLower(a.Project), term) {
			matches = append(matches, a)
		}
	}
	if len(matches) == 0 {
		fmt.Println("No matching activities found")
		return nil
	}
	// Display with original indices based on position in prior list
	// Let's map activity back to its index in prior
	idxOf := map[*Activity]int{}
	for i, a := range prior {
		idxOf[a] = i
	}
	// Sort matches by idx descending (so [0] appears last)
	sort.SliceStable(matches, func(i, j int) bool {
		return idxOf[matches[i]] > idxOf[matches[j]]
	})
	rows := make([][]string, 0, len(matches))
	for _, a := range matches {
		rows = append(rows, []string{
			fmt.Sprintf("[%d]", idxOf[a]),
			a.Description,
			a.Project,
		})
	}
	writeTable([]string{" # ", "Description", "Project"}, rows, nil)
	return nil
}

func cmdProjects(cli *cliArgs) error {
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	seen := map[string]bool{}
	for _, a := range log.Activities {
		if cli.currentFlag && !a.IsRunning() {
			continue
		}
		seen[a.Project] = true
	}
	var projs []string
	for p := range seen {
		projs = append(projs, p)
	}
	sort.Strings(projs)
	for _, p := range projs {
		if cli.noQuotes {
			fmt.Println(p)
		} else {
			fmt.Printf("%q\n", p)
		}
	}
	return nil
}

