func cmdStatus(cli *cliArgs) error {
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	now := time.Now()
	project := ""
	if cli.project != nil {
		project = *cli.project
	}

	// Compute durations for Today, current week, current month
	today := midnight(now)
	weekStart := startOfWeek(now)
	monthStart := time.Date(now.Year(), now.Month(), 1, 0, 0, 0, 0, now.Location())

	matchesProject := func(p string) bool {
		if project == "" {
			return true
		}
		return p == project
	}
	sumBetween := func(from time.Time) time.Duration {
		var total time.Duration
		for _, a := range log.Activities {
			if !matchesProject(a.Project) {
				continue
			}
			end := a.End
			if a.IsRunning() {
				end = now
			}
			start := a.Start
			if end.Before(from) {
				continue
			}
			if start.Before(from) {
				start = from
			}
			if end.After(now) {
				end = now
			}
			total += end.Sub(start)
			_ = end
		}
		return total
	}
	todayDur := sumBetween(today)
	weekDur := sumBetween(weekStart)
	monthDur := sumBetween(monthStart)

	// Find running activity (first one matching project)
	var running *Activity
	for _, a := range log.Activities {
		if a.IsRunning() && matchesProject(a.Project) {
			running = a
			break
		}
	}

	// Header line
	fmt.Print(ansiDim)
	fmt.Print("\n =======")
	fmt.Print(ansiReset)
	if project == "" {
		fmt.Print(ansiItalic)
		fmt.Print(" Status for ")
		fmt.Print(ansiReset)
		fmt.Print(ansiBold)
		fmt.Print("ALL")
		fmt.Print(ansiReset)
		fmt.Print(ansiItalic)
		fmt.Print(" projects ")
		fmt.Print(ansiReset)
	} else {
		fmt.Print(ansiItalic)
		fmt.Print(" Status for project: ")
		fmt.Print(ansiReset)
		fmt.Print(ansiBold)
		fmt.Print(project)
		fmt.Print(ansiReset)
	}
	fmt.Print(ansiDim)
	fmt.Print(" ======= \n")
	fmt.Print(ansiReset)

	// NOW line
	fmt.Print(ansiDimItalic)
	fmt.Print("\n  NOW: ")
	fmt.Print(ansiReset)
	if running == nil {
		fmt.Print(ansiBold)
		fmt.Print(" NO Activity\n\n")
		fmt.Print(ansiReset)
	} else {
		// "desc on proj" (or just desc if -p)
		fmt.Print(ansiBoldGreen)
		fmt.Print(running.Description)
		fmt.Print(ansiReset)
		if project == "" {
			fmt.Print(ansiDimItalic)
			fmt.Print(" on ")
			fmt.Print(ansiReset)
			fmt.Print(ansiItalic)
			fmt.Print(running.Project)
			fmt.Print(ansiReset)
		}
		fmt.Print(ansiDim)
		fmt.Print(" ...... ")
		fmt.Print(ansiReset)
		fmt.Print(ansiBold)
		fmt.Print(formatDuration(now.Sub(running.Start)))
		fmt.Print(ansiReset)
		fmt.Print(ansiDim)
		fmt.Print("\n\n")
		fmt.Print(ansiReset)
	}

	// Today / Current week / Current month: label padded with dots to width 32.
	const labelW = 32
	printStatusLine := func(label string, dur time.Duration) {
		// prefix: italic " "
		fmt.Print(ansiItalic)
		fmt.Print(" ")
		fmt.Print(ansiReset)
		// label + dots
		full := " " + label
		full = padDots(full, labelW)
		fmt.Print(ansiDimItalic)
		fmt.Print(full + " ")
		fmt.Print(ansiReset)
		fmt.Print(ansiBold)
		fmt.Print(formatDuration(dur))
		fmt.Print(ansiReset)
		fmt.Print(ansiItalic)
		fmt.Print("\n")
		fmt.Print(ansiReset)
	}
	printStatusLine("Today", todayDur)
	printStatusLine("Current week", weekDur)
	printStatusLine("Current month", monthDur)
	fmt.Println()
	return nil
}

