// collectLastActivities returns unique (description, project) pairs in reverse
// chronological order of last appearance.
func collectLastActivities(log *Log, limit int) []*Activity {
	// Reverse iterate log entries, dedupe by (desc, proj).
	seen := map[string]bool{}
	var out []*Activity
	for i := len(log.Activities) - 1; i >= 0; i-- {
		a := log.Activities[i]
		k := a.Project + "\x00" + a.Description
		if seen[k] {
			continue
		}
		seen[k] = true
		out = append(out, a)
		if limit > 0 && len(out) >= limit {
			break
		}
	}
	return out
}

