	at := now
	timeSet := false
	if cli.timeStr != nil {
		t, err := parseTimeArg(*cli.timeStr, now)
		if err != nil {
			fmt.Println(err.Error())
		} else {
			at = t
			timeSet = true
		}
	}
	if cli.description == nil && cli.project == nil && !timeSet {
		// Nothing to change
		return nil
	}
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	changed := false
	for _, e := range log.Entries {
		if e.Activity == nil || !e.Activity.IsRunning() {
			continue
		}
		a := e.Activity
		if cli.description != nil {
			a.Description = *cli.description
		}
		if cli.project != nil {
			a.Project = *cli.project
		}
		if timeSet {
			a.Start = at
		}
		fmt.Printf("Changed activity: %q (%s) started at %s\n",
			a.Description, a.Project, a.Start.Format("2006-01-02 15:04"))
		changed = true
	}
	if changed {
		return rewriteFile(cli.file, log.Entries)
	}
	return nil
}

