func filterByOptions(log *Log, cli *cliArgs) []*Activity {
	acts := log.Activities
	now := time.Now()

	// date range filter
	var fromDate, toDate *time.Time
	if cli.today {
		t := midnight(now)
		fromDate = &t
		end := t
		toDate = &end
	} else if cli.yesterday {
		t := midnight(now).AddDate(0, 0, -1)
		fromDate = &t
		end := t
		toDate = &end
	} else if cli.currentWeek {
		start := startOfWeek(now)
		end := start.AddDate(0, 0, 6)
		fromDate = &start
		toDate = &end
	} else if cli.lastWeek {
		start := startOfWeek(now).AddDate(0, 0, -7)
		end := start.AddDate(0, 0, 6)
		fromDate = &start
		toDate = &end
	}

	if cli.dateStr != nil {
		d, err := parseDateArg(*cli.dateStr)
		if err != nil {
			fmt.Println(err.Error())
		} else {
			fromDate = &d
			td := d
			toDate = &td
		}
	}
	if cli.fromDateStr != nil {
		d, err := parseDateFromTo(*cli.fromDateStr)
		if err != nil {
			fmt.Println(err.Error())
		} else {
			fromDate = &d
		}
	}
	if cli.toDateStr != nil {
		d, err := parseDateFromTo(*cli.toDateStr)
		if err != nil {
			fmt.Println(err.Error())
		} else {
			toDate = &d
		}
	}

	var filtered []*Activity
	for _, a := range acts {
		if a.IsRunning() {
			continue
		}
		d := startOfDay(a.Start)
		if fromDate != nil && d.Before(*fromDate) {
			continue
		}
		if toDate != nil && d.After(*toDate) {
			continue
		}
		if cli.project != nil && a.Project != *cli.project {
			continue
		}
		filtered = append(filtered, a)
	}
	// sort chronologically
	sort.SliceStable(filtered, func(i, j int) bool {
		return filtered[i].Start.Before(filtered[j].Start)
	})

	// -n limit: take last N entries
	if cli.number != nil {
		n, err := strconv.Atoi(*cli.number)
		if err == nil && n >= 0 && n < len(filtered) {
			filtered = filtered[len(filtered)-n:]
		}
	}

	// rounding
	if cli.roundStr != nil {
		d, ok := parseRound(*cli.roundStr)
		if !ok {
			fmt.Printf("Can not parse %q as duration. Argument for --round is ignored\n", *cli.roundStr)
		} else {
			// Round a copy of each activity
			rounded := make([]*Activity, len(filtered))
			for i, a := range filtered {
				b := *a
				b.Start = roundTime(a.Start, d)
				b.End = roundTime(a.End, d)
				rounded[i] = &b
			}
			filtered = rounded
		}
	}
	return filtered
}

func parseDateFromTo(s string) (time.Time, error) {
	for _, r := range s {
		if !((r >= '0' && r <= '9') || r == '-') {
			return time.Time{}, fmt.Errorf("Can not parse %q as date. Argument for --from/--to is ignored (input contains invalid characters)", s)
		}
	}
	t, err := time.Parse("2006-01-02", s)
	if err != nil {
		return time.Time{}, fmt.Errorf("Can not parse %q as date. Argument for --from/--to is ignored (input is out of range)", s)
	}
	return t, nil
}

func midnight(t time.Time) time.Time {
	return time.Date(t.Year(), t.Month(), t.Day(), 0, 0, 0, 0, t.Location())
}

func startOfDay(t time.Time) time.Time {
	return time.Date(t.Year(), t.Month(), t.Day(), 0, 0, 0, 0, t.Location())
}

// startOfWeek returns the Monday of the week containing t (at 00:00).
func startOfWeek(t time.Time) time.Time {
	t = midnight(t)
	// Weekday: Sun=0..Sat=6 in Go
	wd := int(t.Weekday())
	// Monday-based: Monday=0
	days := (wd + 6) % 7
	return t.AddDate(0, 0, -days)
}

