// Table rendering:
// each row: col1 + NBSP padding to width1 + " " + col2 + NBSP padding + " " + ...
// header: underlined per column.
func writeTable(headers []string, rows [][]string, rowPainter func(i int, s string) string) {
	// compute widths
	widths := make([]int, len(headers))
	for i, h := range headers {
		widths[i] = runeLen(h)
	}
	for _, r := range rows {
		for i, c := range r {
			if runeLen(c) > widths[i] {
				widths[i] = runeLen(c)
			}
		}
	}
	fmt.Println()
	var sb strings.Builder
	for i, h := range headers {
		sb.WriteString(underline(padNBSP(h, widths[i])))
		sb.WriteString(" ")
		_ = i
	}
	fmt.Println(sb.String())
	for idx, r := range rows {
		var rb strings.Builder
		for i, c := range r {
			rb.WriteString(padNBSP(c, widths[i]))
			rb.WriteString(" ")
		}
		line := rb.String()
		if rowPainter != nil {
			line = rowPainter(idx, line)
		}
		fmt.Println(line)
	}
}

// listRow carries the cells for one list row, plus a yellow flag.
type listRow struct {
	started string
	stopped string
	desc    string
	project string
	dur     string
	yellow  bool
}

func printListGrouped(activities []*Activity) {
	// Group by date of start
	groups := map[string][]*Activity{}
	var dates []string
	for _, a := range activities {
		d := a.Start.Format("2006-01-02")
		if _, ok := groups[d]; !ok {
			dates = append(dates, d)
		}
		groups[d] = append(groups[d], a)
	}
	sort.Strings(dates)

	// Build all rows to compute column widths.
	var rowsAll []listRow
	for _, d := range dates {
		for _, a := range groups[d] {
			stopped := a.End.Format("15:04")
			if a.End.Format("2006-01-02") != a.Start.Format("2006-01-02") {
				stopped = a.End.Format("2006-01-02 15:04")
			}
			r := listRow{
				started: a.Start.Format("15:04"),
				stopped: stopped,
				desc:    a.Description,
				project: a.Project,
				dur:     formatDuration(a.End.Sub(a.Start)),
				yellow:  a.End.Format("2006-01-02") != a.Start.Format("2006-01-02"),
			}
			rowsAll = append(rowsAll, r)
		}
	}

	w := [5]int{
		runeLen("Started"),
		runeLen("Stopped"),
		runeLen("Description"),
		runeLen("Project"),
		runeLen("Duration"),
	}
	for _, r := range rowsAll {
		if runeLen(r.started) > w[0] {
			w[0] = runeLen(r.started)
		}
		if runeLen(r.stopped) > w[1] {
			w[1] = runeLen(r.stopped)
		}
		if runeLen(r.desc) > w[2] {
			w[2] = runeLen(r.desc)
		}
		if runeLen(r.project) > w[3] {
			w[3] = runeLen(r.project)
		}
		if runeLen(r.dur) > w[4] {
			w[4] = runeLen(r.dur)
		}
	}

	fmt.Println()
	// Header
	var sb strings.Builder
	sb.WriteString(underline(padNBSP("Started", w[0])))
	sb.WriteString(" ")
	sb.WriteString(underline(padNBSP("Stopped", w[1])))
	sb.WriteString(" ")
	sb.WriteString(underline(padNBSP("Description", w[2])))
	sb.WriteString(" ")
	sb.WriteString(underline(padNBSP("Project", w[3])))
	sb.WriteString(" ")
	sb.WriteString(underline(padNBSP("Duration", w[4])))
	sb.WriteString(" ")
	fmt.Println(sb.String())

	idx := 0
	for _, d := range dates {
		fmt.Println()
		// compute group total
		var total time.Duration
		for _, a := range groups[d] {
			total += a.End.Sub(a.Start)
		}
		dt, _ := time.Parse("2006-01-02", d)
		fmt.Println(dayHeader(dt, total))
		for range groups[d] {
			r := rowsAll[idx]
			idx++
			cells := []string{
				padNBSP(r.started, w[0]),
				padNBSP(r.stopped, w[1]),
				padNBSP(r.desc, w[2]),
				padNBSP(r.project, w[3]),
				padNBSP(r.dur, w[4]),
			}
			var lb strings.Builder
			for _, c := range cells {
				if r.yellow {
					lb.WriteString(yellow(c))
				} else {
					lb.WriteString(c)
				}
				lb.WriteString(" ")
			}
			fmt.Println(lb.String())
		}
	}
}

