func cmdReport(cli *cliArgs) error {
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	activities := filterByOptions(log, cli)
	if len(activities) == 0 {
		fmt.Println("No activity to report")
		return nil
	}
	printReport(activities)
	return nil
}

func printReport(activities []*Activity) {
	// Group by project, then by description.
	type descAgg struct {
		Desc string
		Dur  time.Duration
	}
	type projAgg struct {
		Proj string
		Dur  time.Duration
		Desc map[string]time.Duration
	}
	projs := map[string]*projAgg{}
	var order []string
	for _, a := range activities {
		p, ok := projs[a.Project]
		if !ok {
			p = &projAgg{Proj: a.Project, Desc: map[string]time.Duration{}}
			projs[a.Project] = p
			order = append(order, a.Project)
		}
		d := a.End.Sub(a.Start)
		p.Dur += d
		p.Desc[a.Description] += d
	}
	sort.Strings(order)
	var total time.Duration

	// compute label widths
	labelWidth := runeLen("Total")
	for _, pname := range order {
		if runeLen(pname) > labelWidth {
			labelWidth = runeLen(pname)
		}
		for desc := range projs[pname].Desc {
			w := runeLen(desc) + 4
			if w > labelWidth {
				labelWidth = w
			}
		}
	}
	// compute duration width
	durWidth := 0
	for _, pname := range order {
		total += projs[pname].Dur
		ds := formatDuration(projs[pname].Dur)
		if runeLen(ds) > durWidth {
			durWidth = runeLen(ds)
		}
		for _, d := range projs[pname].Desc {
			ds := formatDuration(d)
			if runeLen(ds) > durWidth {
				durWidth = runeLen(ds)
			}
		}
	}
	ts := formatDuration(total)
	if runeLen(ts) > durWidth {
		durWidth = runeLen(ts)
	}

	fmt.Println()
	for _, pname := range order {
		p := projs[pname]
		// Project line (bold)
		line := padDots(pname, labelWidth) + " " + padLeft(formatDuration(p.Dur), durWidth)
		fmt.Println(bold(line))

		// Activities sorted by description
		descs := make([]string, 0, len(p.Desc))
		for d := range p.Desc {
			descs = append(descs, d)
		}
		sort.Strings(descs)
		for _, desc := range descs {
			label := "    " + desc
			line := padDots(label, labelWidth) + " " + padLeft(formatDuration(p.Desc[desc]), durWidth)
			fmt.Println(line)
		}
		fmt.Println()
	}
	line := padDots("Total", labelWidth) + " " + padLeft(ts, durWidth)
	fmt.Println(bold(line))
	fmt.Println()
}

// padDots pads s with dots up to width.
func padDots(s string, width int) string {
	visual := runeLen(s)
	if visual >= width {
		return s
	}
	return s + strings.Repeat(".", width-visual)
}

// padLeft pads s with spaces to the left up to width.
func padLeft(s string, width int) string {
	visual := runeLen(s)
	if visual >= width {
		return s
	}
	return strings.Repeat(" ", width-visual) + s
}

