// removeLinesAndRewrite removes the specified activities' lines from the original file.
func removeLinesAndRewrite(path string, entries []ParsedActivity, toRemove []*Activity) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	origLines := splitLines(string(data))
	skip := map[int]bool{}
	for _, r := range toRemove {
		skip[r.Line] = true
	}
	// Also apply modifications from entries (those that remain).
	mods := map[int]string{}
	for _, e := range entries {
		if e.Activity != nil && !skip[e.Line] {
			mods[e.Line] = formatActivityLine(e.Activity)
		}
	}
	f, err := os.Create(path)
	if err != nil {
		return err
	}
	defer f.Close()
	for i, line := range origLines {
		lineNo := i + 1
		if skip[lineNo] {
			continue
		}
		if v, ok := mods[lineNo]; ok {
			line = v
		}
		if _, err := f.WriteString(line + "\n"); err != nil {
			return err
		}
	}
	return nil
}

