func cmdCheck(cli *cliArgs) error {
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	var errs []ParsedActivity
	for _, e := range log.Entries {
		if e.Activity == nil {
			errs = append(errs, e)
		}
	}
	if len(errs) == 0 {
		fmt.Println("All lines in the file have been successfully parsed as activities.")
		return nil
	}
	fmt.Printf("Found %d line(s) with parsing errors\n", len(errs))
	for _, e := range errs {
		fmt.Println()
		fmt.Println(e.Raw)
		fmt.Printf("  -> %s (Line: %d)\n", e.Err.Error(), e.Line)
	}
	return nil
}

func cmdSanity(cli *cliArgs) error {
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	// Find negative durations
	type negItem struct {
		a *Activity
	}
	var negs []*Activity
	for _, a := range log.Activities {
		if !a.IsRunning() && a.End.Before(a.Start) {
			negs = append(negs, a)
		}
	}
	if len(negs) == 0 {
		fmt.Println("No unusual activities.")
		return nil
	}
	// Sort by line descending? Based on the observed output: file had 
	// two neg entries on lines 1 and 2, output showed line 2 first.
	sort.SliceStable(negs, func(i, j int) bool {
		return negs[i].Line > negs[j].Line
	})
	for _, a := range negs {
		fmt.Println("Activity has negative duration")
		fmt.Printf("%s (Started: %s, Ended: %s, Line: %d)\n\n",
			a.Description,
			a.Start.Format("2006-01-02 15:04"),
			a.End.Format("2006-01-02 15:04"),
			a.Line)
	}
	return nil
}

func cmdEdit(cli *cliArgs) error {
	editor := ""
	if cli.editor != nil {
		editor = *cli.editor
	} else {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		return fmt.Errorf("Error: editor command is missing")
	}
	cmd := exec.Command(editor, cli.file)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		// match clap-style error: "Error: No such file or directory (os error 2)"
		if _, ok := err.(*exec.Error); ok {
			return fmt.Errorf("Error: No such file or directory (os error 2)")
		}
		return fmt.Errorf("Error: %s", err.Error())
	}
	return nil
}
