func parseTimeForToday(s string, now time.Time) (time.Time, bool) {
	// Parse HH:MM; use today's date.
	if len(s) == 0 {
		return time.Time{}, false
	}
	// Check validity: allow any digit-colon-digit format
	t, err := time.Parse("15:04", s)
	if err != nil {
		// Check if it's parseable at all
		// Clap emits two different errors: invalid characters or out of range
		return time.Time{}, false
	}
	return time.Date(now.Year(), now.Month(), now.Day(), t.Hour(), t.Minute(), 0, 0, now.Location()), true
}

// parseTimeArg validates and returns parsed HH:MM or errors with a specific message.
func parseTimeArg(s string, now time.Time) (time.Time, error) {
	// Validate characters: must be digits and colon only
	for _, r := range s {
		if !((r >= '0' && r <= '9') || r == ':') {
			return time.Time{}, fmt.Errorf("Can not parse %q as time. Argument for -t/--time is ignored (input contains invalid characters)", s)
		}
	}
	parts := strings.Split(s, ":")
	if len(parts) != 2 {
		return time.Time{}, fmt.Errorf("Can not parse %q as time. Argument for -t/--time is ignored (input is out of range)", s)
	}
	h, err1 := strconv.Atoi(parts[0])
	m, err2 := strconv.Atoi(parts[1])
	if err1 != nil || err2 != nil {
		return time.Time{}, fmt.Errorf("Can not parse %q as time. Argument for -t/--time is ignored (input contains invalid characters)", s)
	}
	if h < 0 || h > 23 || m < 0 || m > 59 {
		return time.Time{}, fmt.Errorf("Can not parse %q as time. Argument for -t/--time is ignored (input is out of range)", s)
	}
	return time.Date(now.Year(), now.Month(), now.Day(), h, m, 0, 0, now.Location()), nil
}

// parseDateArg parses YYYY-MM-DD
func parseDateArg(s string) (time.Time, error) {
	for _, r := range s {
		if !((r >= '0' && r <= '9') || r == '-') {
			return time.Time{}, fmt.Errorf("Can not parse %q as date. Argument for -d/--date is ignored (input contains invalid characters)", s)
		}
	}
	t, err := time.Parse("2006-01-02", s)
	if err != nil {
		return time.Time{}, fmt.Errorf("Can not parse %q as date. Argument for -d/--date is ignored (input is out of range)", s)
	}
	return t, nil
}

// parseRound parses a duration string like "15m" or "4h"; returns 0 and false if fails.
func parseRound(s string) (time.Duration, bool) {
	// Must begin with digits
	if len(s) == 0 {
		return 0, false
	}
	i := 0
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		i++
	}
	if i == 0 {
		return 0, false
	}
	num, err := strconv.Atoi(s[:i])
	if err != nil {
		return 0, false
	}
	if i >= len(s) {
		return 0, false
	}
	switch s[i] {
	case 'm':
		return time.Duration(num) * time.Minute, true
	case 'h':
		return time.Duration(num) * time.Hour, true
	}
	return 0, false
}

// roundTime rounds t to nearest multiple of d.
func roundTime(t time.Time, d time.Duration) time.Time {
	if d <= 0 {
		return t
	}
	// Round to nearest
	secondsSinceEpoch := t.Unix()
	sec := int64(d / time.Second)
	// Nearest multiple
	rem := secondsSinceEpoch % sec
	if rem*2 < sec {
		return time.Unix(secondsSinceEpoch-rem, 0).In(t.Location())
	}
	return time.Unix(secondsSinceEpoch-rem+sec, 0).In(t.Location())
}

// stopRunningActivities stops all running activities at the given time.
// Returns a slice of stopped activities. Caller is responsible for writing back.
func stopRunningActivities(log *Log, at time.Time) []*Activity {
	var stopped []*Activity
	for _, e := range log.Entries {
		if e.Activity != nil && e.Activity.IsRunning() {
			e.Activity.End = at
			e.Activity.Running = false
			stopped = append(stopped, e.Activity)
		}
	}
	return stopped
}

func cmdStart(cli *cliArgs) error {
	now := time.Now()
	at := now
	if cli.timeStr != nil {
		t, err := parseTimeArg(*cli.timeStr, now)
		if err != nil {
			fmt.Println(err.Error())
		} else {
			at = t
		}
	}

	// Load existing log (if file doesn't exist, create an empty log)
	log, err := loadOrCreate(cli.file)
	if err != nil {
		return err
	}

	// Stop running activities at 'at'
	stopped := stopRunningActivities(log, at)
	for _, s := range stopped {
		fmt.Printf("Stopped activity: %q (%s) started at %s (%s)\n",
			s.Description, s.Project, s.Start.Format("2006-01-02 15:04"),
			formatDuration(s.End.Sub(s.Start)))
	}

	newAct := &Activity{
		Start:       at,
		Project:     *cli.project,
		Description: *cli.description,
		Running:     true,
	}

	// If we need to modify and then append, do both in one go
	if len(stopped) > 0 {
		if err := rewriteFile(cli.file, log.Entries); err != nil {
			return err
		}
	}
	if err := appendLine(cli.file, formatActivityLine(newAct)); err != nil {
		return err
	}
	fmt.Printf("Started activity: %q (%s) at %s\n", newAct.Description, newAct.Project, newAct.Start.Format("2006-01-02 15:04"))
	return nil
}

func loadOrCreate(path string) (*Log, error) {
	if _, err := os.Stat(path); os.IsNotExist(err) {
		return &Log{Path: path}, nil
	}
	return loadLog(path)
}

func cmdStop(cli *cliArgs) error {
	now := time.Now()
	at := now
	if cli.timeStr != nil {
