func cmdContinue(cli *cliArgs) error {
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	// Collect unique activities in reverse order of last appearance
	prior := collectLastActivities(log, 0)
	if len(prior) == 0 {
		return fmt.Errorf("Error: No activity has been started before.")
	}
	n := cli.continueNumber
	if n < 0 {
		n = 0
	}
	if n >= len(prior) {
		return fmt.Errorf("Error: Less than %d distinct activities have been logged yet", n)
	}
	// prior[0] is most recent. Continue index n.
	act := prior[n]
	desc := act.Description
	proj := act.Project
	if cli.description != nil {
		desc = *cli.description
	}
	if cli.project != nil {
		proj = *cli.project
	}
	now := time.Now()
	at := now
	if cli.timeStr != nil {
		t, err := parseTimeArg(*cli.timeStr, now)
		if err != nil {
			fmt.Println(err.Error())
		} else {
			at = t
		}
	}
	// Stop running activities first
	stopped := stopRunningActivities(log, at)
	for _, s := range stopped {
		fmt.Printf("Stopped activity: %q (%s) started at %s (%s)\n",
			s.Description, s.Project, s.Start.Format("2006-01-02 15:04"),
			formatDuration(s.End.Sub(s.Start)))
	}
	if len(stopped) > 0 {
		if err := rewriteFile(cli.file, log.Entries); err != nil {
			return err
		}
	}
	newAct := &Activity{
		Start:       at,
		Project:     proj,
		Description: desc,
		Running:     true,
	}
	if err := appendLine(cli.file, formatActivityLine(newAct)); err != nil {
		return err
	}
	fmt.Printf("Started activity: %q (%s) at %s\n", newAct.Description, newAct.Project, newAct.Start.Format("2006-01-02 15:04"))
	return nil
}

// collectLastActivities returns unique (description, project) pairs in reverse
// chronological order of last appearance.
func collectLastActivities(log *Log, limit int) []*Activity {
	// Reverse iterate log entries, dedupe by (desc, proj).
	seen := map[string]bool{}
	var out []*Activity
	for i := len(log.Activities) - 1; i >= 0; i-- {
		a := log.Activities[i]
		k := a.Project + "\x00" + a.Description
		if seen[k] {
			continue
		}
		seen[k] = true
		out = append(out, a)
		if limit > 0 && len(out) >= limit {
			break
		}
	}
	return out
}

func cmdChange(cli *cliArgs) error {
	now := time.Now()
	at := now
	timeSet := false
	if cli.timeStr != nil {
		t, err := parseTimeArg(*cli.timeStr, now)
		if err != nil {
			fmt.Println(err.Error())
		} else {
			at = t
			timeSet = true
		}
	}
	if cli.description == nil && cli.project == nil && !timeSet {
		// Nothing to change
		return nil
	}
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	changed := false
	for _, e := range log.Entries {
		if e.Activity == nil || !e.Activity.IsRunning() {
			continue
		}
		a := e.Activity
		if cli.description != nil {
			a.Description = *cli.description
		}
		if cli.project != nil {
			a.Project = *cli.project
		}
		if timeSet {
			a.Start = at
		}
		fmt.Printf("Changed activity: %q (%s) started at %s\n",
			a.Description, a.Project, a.Start.Format("2006-01-02 15:04"))
		changed = true
	}
	if changed {
		return rewriteFile(cli.file, log.Entries)
	}
	return nil
}

