func cmdReport(cli *cliArgs) error {
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	activities := filterByOptions(log, cli)
	if len(activities) == 0 {
		fmt.Println("No activity to report")
		return nil
	}
	printReport(activities)
	return nil
}

func printReport(activities []*Activity) {
	// Group by project, then by description.
	type descAgg struct {
		Desc string
		Dur  time.Duration
	}
	type projAgg struct {
		Proj string
		Dur  time.Duration
		Desc map[string]time.Duration
	}
	projs := map[string]*projAgg{}
	var order []string
	for _, a := range activities {
		p, ok := projs[a.Project]
		if !ok {
			p = &projAgg{Proj: a.Project, Desc: map[string]time.Duration{}}
			projs[a.Project] = p
			order = append(order, a.Project)
		}
		d := a.End.Sub(a.Start)
		p.Dur += d
		p.Desc[a.Description] += d
	}
	sort.Strings(order)
	var total time.Duration

	// compute label widths
	labelWidth := runeLen("Total")
	for _, pname := range order {
		if runeLen(pname) > labelWidth {
			labelWidth = runeLen(pname)
		}
		for desc := range projs[pname].Desc {
			w := runeLen(desc) + 4
			if w > labelWidth {
				labelWidth = w
			}
		}
	}
	// compute duration width
	durWidth := 0
	for _, pname := range order {
		total += projs[pname].Dur
		ds := formatDuration(projs[pname].Dur)
		if runeLen(ds) > durWidth {
			durWidth = runeLen(ds)
		}
		for _, d := range projs[pname].Desc {
			ds := formatDuration(d)
			if runeLen(ds) > durWidth {
				durWidth = runeLen(ds)
			}
		}
	}
	ts := formatDuration(total)
	if runeLen(ts) > durWidth {
		durWidth = runeLen(ts)
	}

	fmt.Println()
	for _, pname := range order {
		p := projs[pname]
		// Project line (bold)
		line := padDots(pname, labelWidth) + " " + padLeft(formatDuration(p.Dur), durWidth)
		fmt.Println(bold(line))

		// Activities sorted by description
		descs := make([]string, 0, len(p.Desc))
		for d := range p.Desc {
			descs = append(descs, d)
		}
		sort.Strings(descs)
		for _, desc := range descs {
			label := "    " + desc
			line := padDots(label, labelWidth) + " " + padLeft(formatDuration(p.Desc[desc]), durWidth)
			fmt.Println(line)
		}
		fmt.Println()
	}
	line := padDots("Total", labelWidth) + " " + padLeft(ts, durWidth)
	fmt.Println(bold(line))
	fmt.Println()
}

// padDots pads s with dots up to width.
func padDots(s string, width int) string {
	visual := runeLen(s)
	if visual >= width {
		return s
	}
	return s + strings.Repeat(".", width-visual)
}

// padLeft pads s with spaces to the left up to width.
func padLeft(s string, width int) string {
	visual := runeLen(s)
	if visual >= width {
		return s
	}
	return strings.Repeat(" ", width-visual) + s
}

// -----------------------------------------------------------------------------
// last / search / projects / status / check / sanity / edit
// -----------------------------------------------------------------------------

func cmdLast(cli *cliArgs) error {
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	limit := 10
	if cli.number != nil {
		if n, err := strconv.Atoi(*cli.number); err == nil && n > 0 {
			limit = n
		}
	}
	prior := collectLastActivities(log, limit)
	if len(prior) == 0 {
		return fmt.Errorf("Error: No activity has been started before.")
	}
	// Print in ascending order (highest index first, then [0] at bottom)
	// prior[0] is most recent. We display in reverse.
	rows := make([][]string, 0, len(prior))
	for i := len(prior) - 1; i >= 0; i-- {
		rows = append(rows, []string{
			fmt.Sprintf("[%d]", i),
			prior[i].Description,
			prior[i].Project,
		})
	}
	writeTable([]string{" # ", "Description", "Project"}, rows, nil)
	return nil
}

func cmdSearch(cli *cliArgs) error {
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	term := strings.ToLower(cli.searchTerm)
	prior := collectLastActivities(log, 0)
	var matches []*Activity
	for _, a := range prior {
		if strings.Contains(strings.ToLower(a.Description), term) || strings.Contains(strings.ToLower(a.Project), term) {
			matches = append(matches, a)
		}
	}
	if len(matches) == 0 {
		fmt.Println("No matching activities found")
		return nil
	}
	// Display with original indices based on position in prior list
	// Let's map activity back to its index in prior
	idxOf := map[*Activity]int{}
	for i, a := range prior {
		idxOf[a] = i
	}
	// Sort matches by idx descending (so [0] appears last)
	sort.SliceStable(matches, func(i, j int) bool {
		return idxOf[matches[i]] > idxOf[matches[j]]
	})
	rows := make([][]string, 0, len(matches))
	for _, a := range matches {
		rows = append(rows, []string{
			fmt.Sprintf("[%d]", idxOf[a]),
			a.Description,
			a.Project,
		})
	}
	writeTable([]string{" # ", "Description", "Project"}, rows, nil)
	return nil
}

func cmdProjects(cli *cliArgs) error {
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	seen := map[string]bool{}
	for _, a := range log.Activities {
		if cli.currentFlag && !a.IsRunning() {
			continue
		}
		seen[a.Project] = true
	}
	var projs []string
	for p := range seen {
		projs = append(projs, p)
	}
	sort.Strings(projs)
	for _, p := range projs {
		if cli.noQuotes {
			fmt.Println(p)
		} else {
			fmt.Printf("%q\n", p)
		}
	}
	return nil
}

// -----------------------------------------------------------------------------
// status
// -----------------------------------------------------------------------------

func cmdStatus(cli *cliArgs) error {
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	now := time.Now()
	project := ""
	if cli.project != nil {
		project = *cli.project
	}

	// Compute durations for Today, current week, current month
	today := midnight(now)
	weekStart := startOfWeek(now)
	monthStart := time.Date(now.Year(), now.Month(), 1, 0, 0, 0, 0, now.Location())

	matchesProject := func(p string) bool {
		if project == "" {
			return true
		}
		return p == project
	}
	sumBetween := func(from time.Time) time.Duration {
		var total time.Duration
		for _, a := range log.Activities {
			if !matchesProject(a.Project) {
				continue
			}
			end := a.End
			if a.IsRunning() {
				end = now
			}
			start := a.Start
			if end.Before(from) {
				continue
			}
			if start.Before(from) {
				start = from
			}
			if end.After(now) {
				end = now
			}
			total += end.Sub(start)
			_ = end
		}
		return total
	}
	todayDur := sumBetween(today)
	weekDur := sumBetween(weekStart)
	monthDur := sumBetween(monthStart)

	// Find running activity (first one matching project)
	var running *Activity
	for _, a := range log.Activities {
		if a.IsRunning() && matchesProject(a.Project) {
			running = a
			break
		}
	}

	// Header line
	fmt.Print(ansiDim)
	fmt.Print("\n =======")
	fmt.Print(ansiReset)
	if project == "" {
		fmt.Print(ansiItalic)
		fmt.Print(" Status for ")
		fmt.Print(ansiReset)
		fmt.Print(ansiBold)
		fmt.Print("ALL")
		fmt.Print(ansiReset)
		fmt.Print(ansiItalic)
		fmt.Print(" projects ")
		fmt.Print(ansiReset)
	} else {
		fmt.Print(ansiItalic)
		fmt.Print(" Status for project: ")
		fmt.Print(ansiReset)
		fmt.Print(ansiBold)
		fmt.Print(project)
		fmt.Print(ansiReset)
	}
	fmt.Print(ansiDim)
	fmt.Print(" ======= \n")
	fmt.Print(ansiReset)

	// NOW line
	fmt.Print(ansiDimItalic)
	fmt.Print("\n  NOW: ")
	fmt.Print(ansiReset)
	if running == nil {
		fmt.Print(ansiBold)
		fmt.Print(" NO Activity\n\n")
		fmt.Print(ansiReset)
	} else {
		// "desc on proj" (or just desc if -p)
		fmt.Print(ansiBoldGreen)
		fmt.Print(running.Description)
		fmt.Print(ansiReset)
		if project == "" {
			fmt.Print(ansiDimItalic)
			fmt.Print(" on ")
			fmt.Print(ansiReset)
			fmt.Print(ansiItalic)
			fmt.Print(running.Project)
			fmt.Print(ansiReset)
		}
		fmt.Print(ansiDim)
		fmt.Print(" ...... ")
		fmt.Print(ansiReset)
		fmt.Print(ansiBold)
		fmt.Print(formatDuration(now.Sub(running.Start)))
		fmt.Print(ansiReset)
		fmt.Print(ansiDim)
		fmt.Print("\n\n")
		fmt.Print(ansiReset)
	}

	// Today / Current week / Current month: label padded with dots to width 32.
	const labelW = 32
	printStatusLine := func(label string, dur time.Duration) {
		// prefix: italic " "
		fmt.Print(ansiItalic)
		fmt.Print(" ")
		fmt.Print(ansiReset)
		// label + dots
		full := " " + label
		full = padDots(full, labelW)
		fmt.Print(ansiDimItalic)
		fmt.Print(full + " ")
		fmt.Print(ansiReset)
		fmt.Print(ansiBold)
		fmt.Print(formatDuration(dur))
		fmt.Print(ansiReset)
		fmt.Print(ansiItalic)
		fmt.Print("\n")
		fmt.Print(ansiReset)
	}
	printStatusLine("Today", todayDur)
	printStatusLine("Current week", weekDur)
	printStatusLine("Current month", monthDur)
	fmt.Println()
	return nil
}

// -----------------------------------------------------------------------------
// check / sanity
// -----------------------------------------------------------------------------

func cmdCheck(cli *cliArgs) error {
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	var errs []ParsedActivity
	for _, e := range log.Entries {
		if e.Activity == nil {
			errs = append(errs, e)
		}
	}
	if len(errs) == 0 {
		fmt.Println("All lines in the file have been successfully parsed as activities.")
		return nil
	}
	fmt.Printf("Found %d line(s) with parsing errors\n", len(errs))
	for _, e := range errs {
		fmt.Println()
		fmt.Println(e.Raw)
		fmt.Printf("  -> %s (Line: %d)\n", e.Err.Error(), e.Line)
	}
	return nil
}

func cmdSanity(cli *cliArgs) error {
	log, err := loadLog(cli.file)
	if err != nil {
		return err
	}
	// Find negative durations
	type negItem struct {
		a *Activity
	}
	var negs []*Activity
	for _, a := range log.Activities {
		if !a.IsRunning() && a.End.Before(a.Start) {
			negs = append(negs, a)
		}
	}
	if len(negs) == 0 {
		fmt.Println("No unusual activities.")
		return nil
	}
	// Sort by line descending? Based on the observed output: file had 
	// two neg entries on lines 1 and 2, output showed line 2 first.
	sort.SliceStable(negs, func(i, j int) bool {
		return negs[i].Line > negs[j].Line
	})
	for _, a := range negs {
		fmt.Println("Activity has negative duration")
		fmt.Printf("%s (Started: %s, Ended: %s, Line: %d)\n\n",
			a.Description,
			a.Start.Format("2006-01-02 15:04"),
			a.End.Format("2006-01-02 15:04"),
			a.Line)
	}
	return nil
}

func cmdEdit(cli *cliArgs) error {
	editor := ""
	if cli.editor != nil {
		editor = *cli.editor
	} else {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		return fmt.Errorf("Error: editor command is missing")
	}
	cmd := exec.Command(editor, cli.file)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		// match clap-style error: "Error: No such file or directory (os error 2)"
		if _, ok := err.(*exec.Error); ok {
			return fmt.Errorf("Error: No such file or directory (os error 2)")
		}
		return fmt.Errorf("Error: %s", err.Error())
	}
	return nil
}
